using FitHub.Domain.Communications;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace FitHub.Infrastructure.Persistence.Configurations;
public sealed class NotificationConfiguration:EntityConfiguration<Notification>{protected override void ConfigureEntity(EntityTypeBuilder<Notification> builder){builder.Property(x=>x.Title).HasMaxLength(200).IsRequired();builder.Property(x=>x.Message).HasMaxLength(4000).IsRequired();builder.Property(x=>x.Type).HasConversion<string>().HasMaxLength(80);builder.Property(x=>x.DeduplicationKey).HasMaxLength(200).IsRequired();builder.HasOne(x=>x.User).WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade);builder.HasIndex(x=>new{x.UserId,x.IsRead,x.CreatedAt});builder.HasIndex(x=>new{x.UserId,x.DeduplicationKey}).IsUnique();}}
